#!/usr/bin/env bash
# Question 12: Errors of a crashed container. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/logs
mkdir -p /opt/course/logs
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q12_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q12_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q12_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q12_NS}" delete pod pay-0 --ignore-not-found --wait=true >/dev/null
token=$(head -c 4 /dev/urandom | od -An -tx1 | tr -d ' \n')
kubectl apply -f - <<EOF >/dev/null
apiVersion: v1
kind: Pod
metadata:
  name: pay-0
  namespace: ${Q12_NS}
spec:
  containers:
    - name: api
      image: busybox:1.36
      command:
        - sh
        - -c
        - |
          if [ ! -f /state/crashed ]; then
            echo "INFO starting payment api run=$token"
            echo "ERROR cannot reach ledger at ledger:5432 run=$token"
            echo "INFO retrying in 1s"
            echo "ERROR ledger still down, giving up run=$token"
            touch /state/crashed
            exit 3
          fi
          echo "INFO payment api up"
          while true; do echo "INFO healthy"; sleep 30; done
      volumeMounts: [{ name: state, mountPath: /state }]
    - name: proxy
      image: busybox:1.36
      command: ["sh", "-c", "echo 'ERROR proxy upstream api not ready yet'; echo 'INFO proxy listening on 8080'; sleep infinity"]
  volumes:
    - name: state
      emptyDir: {}
EOF
for _ in $(seq 1 60); do
  [[ "$(kubectl -n "${Q12_NS}" get pod pay-0 -o jsonpath='{.status.containerStatuses[?(@.name=="api")].restartCount}')" -ge 1 ]] && break
  sleep 2
done
kubectl -n "${Q12_NS}" wait --for=condition=Ready pod/pay-0 --timeout=120s >/dev/null
: "${Q12_NS}"
